args.content:
def apply_discount(price: float, percent: float) -> float:
    """Return price reduced by `percent` percent, rounded to 2 decimals.

    Implements the README spec: `price` reduced by `percent` percent.
    e.g. 15% off 100.00 -> 85.00.
    """
    return round(price - (price * percent / 100.0), 2)
